\documentclass[11pt]{article}
\usepackage{amsmath}

\title{Tutorial Sheet 3: Piecewise Tax Schedules}
\author{Public Economics 302 --- Teaching Team}
\date{September 2026}

\begin{document}
\maketitle

\section{A Two-Bracket Schedule}
Suppose taxable income $x$ (in dollars) is taxed at a marginal rate of
10\% in the first bracket and 22\% above the threshold. The total tax
liability is the continuous piecewise function
\[
T(x) =
\begin{cases}
0.10\,x, & 0 < x \le 30{,}000, & \text{bracket I} \\
3{,}000 + 0.22\,(x - 30{,}000), & x > 30{,}000
\end{cases}
\]
where the second line adds the tax already due on the first
30{,}000 dollars to the marginal amount above the threshold.

\section{Average Versus Marginal Rates}
The average rate $T(x)/x$ rises smoothly towards 22\% as income grows,
while the marginal rate jumps at the bracket boundary. Sketch both
schedules on the same axes and mark the kink at $x = 30{,}000$.

\section{Exercise}
Extend the schedule with a third bracket of 35\% above
90{,}000 dollars, write down the new piecewise function, and compute
the tax due on an income of 120{,}000 dollars.

\end{document}

